<?php
namespace App\Services\Trading;
class PositionManagementPortfolioApprovalService
{public function __construct(protected ?array $config=null){$this->config??=config('trading_position_management_approval');}
 public function approve(array $ctx):array{$candidate=$ctx['management_candidate']??null;$plan=$ctx['action_plan']??null;$impact=$ctx['impact_simulation']??null;$policy=$ctx['management_approval_policy_evaluation']??null;$auth=$ctx['management_authorization_validation']??null;$codes=[];$warnings=[];$blockers=[];$status='unavailable';$elig='action_plan_unavailable';$reference=false;
  if(!is_array($candidate)||($candidate['status']??null)!=='policy_hypothesis'){$elig='management_candidate_unavailable';$this->add($codes,'POSITION_MANAGEMENT_PORTFOLIO_APPROVAL_UNAVAILABLE',$blockers);} elseif(!is_array($plan)||($plan['status']??null)!=='materialized_reference'){$elig='action_plan_unavailable';$this->add($codes,'POSITION_MANAGEMENT_PORTFOLIO_APPROVAL_ACTION_PLAN_REQUIRED',$blockers);} elseif(!is_array($impact)||($impact['status']??null)!=='simulated_reference'){$status='blocked';$elig='impact_simulation_unavailable';$this->add($codes,'POSITION_MANAGEMENT_PORTFOLIO_APPROVAL_IMPACT_REQUIRED',$blockers);$this->add($codes,'POSITION_MANAGEMENT_PORTFOLIO_APPROVAL_IMPACT_RECONCILIATION_FAILED',$blockers);} elseif(!is_array($policy)||($policy['status']??null)==='unavailable'){$elig='approval_policy_unavailable';$this->add($codes,'POSITION_MANAGEMENT_APPROVAL_POLICY_UNAVAILABLE',$blockers);} elseif(($policy['status']??null)!=='eligible_for_authorization'){$status='incomplete';$elig='approval_policy_incomplete';$this->add($codes,'POSITION_MANAGEMENT_APPROVAL_POLICY_REQUIREMENT_FAILED',$blockers);} elseif(!is_array($auth)||($auth['status']??null)==='unavailable'){$status='eligible_for_reference_approval';$elig='authorization_required';$this->add($codes,'POSITION_MANAGEMENT_PORTFOLIO_APPROVAL_ELIGIBLE_REFERENCE');$this->add($codes,'POSITION_MANAGEMENT_PORTFOLIO_APPROVAL_AUTHORIZATION_REQUIRED',$blockers);$this->add($codes,'POSITION_MANAGEMENT_NO_AUTO_APPROVAL_FROM_RISK_REDUCTION',$blockers);} elseif(($auth['status']??null)==='expired'){$status='blocked';$elig='authorization_expired';$this->add($codes,'POSITION_MANAGEMENT_AUTHORIZATION_EXPIRED',$blockers);} elseif(($auth['status']??null)==='denied_reference'){$status='denied_reference';$elig='authorization_denied';$this->add($codes,'POSITION_MANAGEMENT_PORTFOLIO_APPROVAL_DENIED_REFERENCE',$blockers);} elseif(($auth['status']??null)!=='valid_reference_authorization'){$status='blocked';$elig='authorization_invalid';$this->add($codes,'POSITION_MANAGEMENT_AUTHORIZATION_INVALID',$blockers);} else {$status='approved_reference';$elig='approved_reference';$reference=true;$this->add($codes,'POSITION_MANAGEMENT_PORTFOLIO_APPROVAL_APPROVED_REFERENCE');}
  foreach(['POSITION_MANAGEMENT_PORTFOLIO_APPROVAL_PRODUCTION_NOT_IMPLEMENTED','POSITION_MANAGEMENT_PORTFOLIO_APPROVAL_EXECUTION_NOT_IMPLEMENTED','POSITION_MANAGEMENT_APPROVED_ACTION_UNAVAILABLE','POSITION_MANAGEMENT_APPROVED_QUANTITY_UNAVAILABLE','POSITION_MANAGEMENT_PORTFOLIO_APPROVAL_NON_EXECUTABLE_REFERENCE'] as $c)$this->add($codes,$c,$blockers);
  $r=['schema_version'=>$this->config['portfolio_approval_schema_version'],'status'=>$status,'approval_scope'=>'management_action_reference','portfolio_id'=>$policy['portfolio_id']??null,'position_id'=>$plan['position_id']??($candidate['position_id']??null),'management_candidate_id'=>$candidate['candidate_id']??null,'action_plan_id'=>$plan['action_plan_id']??null,'proposed_management_action'=>$plan['proposed_management_action']??null,'proposed_quantity_reference'=>$plan['quantity_plan']['proposed_quantity_reference']??null,'eligibility'=>$elig,'policy_evaluation'=>$policy??[],'authorization_validation'=>$auth??[],'approval_result'=>['reference_approved'=>$reference,'production_approved'=>false,'execution_approved'=>false],'reference_proposal_snapshot'=>['proposed_management_action'=>$plan['proposed_management_action']??null,'proposed_quantity_reference'=>$plan['quantity_plan']['proposed_quantity_reference']??null,'remaining_quantity_reference'=>$plan['quantity_plan']['remaining_quantity_reference']??null,'local_impact_status'=>$impact['status']??null,'portfolio_impact_status'=>$impact['portfolio_impact']['status']??null],'approved_management_action'=>null,'approved_quantity'=>null,'approved_instruction'=>null,'reason_codes'=>$this->ordered($codes),'warnings'=>$this->ordered($warnings),'blockers'=>$this->ordered($blockers),'metadata'=>['reference_only'=>true]];$this->validateApproval($r);return $r;}
 public function validateApproval($r):void{if(($r['schema_version']??null)!==$this->config['portfolio_approval_schema_version'])throw new \InvalidArgumentException('bad management approval schema');if(($r['approval_result']['production_approved']??null)!==false||($r['approval_result']['execution_approved']??null)!==false)throw new \InvalidArgumentException('prod exec forbidden');if(($r['approved_management_action']??null)!==null||($r['approved_quantity']??null)!==null||($r['approved_instruction']??null)!==null)throw new \InvalidArgumentException('approved executable fields forbidden');if(($r['status']??null)==='approved_reference'&&(($r['authorization_validation']['status']??null)!=='valid_reference_authorization'))throw new \InvalidArgumentException('approved without auth');}
 protected function add(&$c,$code,&$target=null):void{if(!in_array($code,$c,true))$c[]=$code;if(is_array($target)&&!in_array($code,$target,true))$target[]=$code;} protected function ordered($c):array{sort($c);return array_values(array_unique($c));}}
